import{_ as t,c as a,o,a3 as n}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Get started with finance","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/get-started/index.md","filePath":"master/finance/get-started/index.md","lastUpdated":1791902625000}'),s={name:"master/finance/get-started/index.md"};function r(i,e,c,u,l,h){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="get-started-with-finance" tabindex="-1">Get started with finance <a class="header-anchor" href="#get-started-with-finance" aria-label="Permalink to &quot;Get started with finance&quot;">​</a></h1><p>Finance in Aureus ERP is where your sales, purchases and payments turn into accounting records. Before you send your first invoice, a few things must be in place: the accounting set-up for your company, a chart of accounts, journals, default accounts and taxes. This group of pages walks you through each of them and shows the dashboard you will use every day.</p><blockquote><p><strong>In simple words:</strong> Do the set-up once, in the right order. After that, every invoice, bill and payment posts to the correct accounts by itself.</p></blockquote><h2 id="two-apps-one-set-of-screens" tabindex="-1">Two apps, one set of screens <a class="header-anchor" href="#two-apps-one-set-of-screens" aria-label="Permalink to &quot;Two apps, one set of screens&quot;">​</a></h2><p>Aureus has two apps for finance. The <strong>Invoices</strong> app is the light one. It covers invoices, bills, payments and the basic configuration. The <strong>Accounting</strong> app has all of that plus the Overview dashboard, journal entries, reports, the chart of accounts, journals, fiscal positions and the accounting settings.</p><p>The pages in this group are mostly for the <strong>Accounting</strong> app. Each page tells you where a screen exists in both apps and where it exists in only one.</p><h2 id="what-is-in-this-group" tabindex="-1">What is in this group <a class="header-anchor" href="#what-is-in-this-group" aria-label="Permalink to &quot;What is in this group&quot;">​</a></h2><ul><li><a href="./accounting-setup.html">Set up accounting</a>: the one-time step that creates the chart of accounts, journals and defaults for a company.</li><li><a href="./accounting-overview.html">Accounting Overview</a>: the dashboard with one card per journal.</li><li><a href="./chart-of-accounts.html">Chart of accounts</a>: the list of accounts where every amount is recorded.</li><li><a href="./journals.html">Journals</a>: the books that group your entries, such as Customer Invoices and Bank.</li><li><a href="./default-accounts.html">Default accounts</a>: the accounts Aureus uses when you do not choose one.</li><li><a href="./multi-currency.html">Foreign currencies</a>: invoices, bills and payments in a currency other than your own.</li></ul><h2 id="set-up-in-this-order" tabindex="-1">Set up in this order <a class="header-anchor" href="#set-up-in-this-order" aria-label="Permalink to &quot;Set up in this order&quot;">​</a></h2><ol><li><strong>Set up accounting</strong> for your company. See <a href="./accounting-setup.html">Set up accounting</a>.</li><li>Check the <strong>chart of accounts</strong> and add any account you need. See <a href="./chart-of-accounts.html">Chart of accounts</a>.</li><li>Check your <strong>journals</strong>. Add a Bank journal for each real bank account. See <a href="./journals.html">Journals</a>.</li><li>Review the <strong>default accounts</strong>. See <a href="./default-accounts.html">Default accounts</a>.</li><li>Set up your <strong>taxes</strong>. See <a href="./../taxes/">Taxes</a>.</li><li>If you sell or buy in other currencies, activate them and add a rate. See <a href="./multi-currency.html">Foreign currencies</a>.</li><li>Create your first invoice. See <a href="./../customer-invoices/">Customer invoices</a>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Steps 2 to 4 are already done for you when you run <strong>Set up accounting</strong>. Read them as a check, not as work you must repeat.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Finance overview</a></li><li><a href="./../taxes/">Taxes</a></li><li><a href="./../customer-invoices/">Customer invoices</a></li><li><a href="./../vendor-bills/">Vendor bills</a></li></ul>',13)]))}const f=t(s,[["render",r]]);export{p as __pageData,f as default};
